from fastapi.sse import ServerSentEvent, format_sse_event
from pydantic import ValidationError
import pytest

def test_server_sent_event_validation():
    # Test valid
    ServerSentEvent(event="hello", id="1")

    # Test invalid event (newline)
    try:
        ServerSentEvent(event="hello\nworld")
    except ValidationError as e:
        # Pydantic ValidationError contains the error messages
        errors = e.errors()
        assert any("SSE 'event' must not contain newlines" in str(err['msg']) for err in errors)
    else:
        pytest.fail("Should have raised ValidationError for event newline")

    # Test invalid id (newline)
    try:
        ServerSentEvent(id="1\n2")
    except ValidationError as e:
        errors = e.errors()
        assert any("SSE 'id' must not contain newlines" in str(err['msg']) for err in errors)
    else:
        pytest.fail("Should have raised ValidationError for id newline")

    # Test invalid id (null)
    try:
        ServerSentEvent(id="1\02")
    except ValidationError as e:
        errors = e.errors()
        assert any("SSE 'id' must not contain null characters" in str(err['msg']) for err in errors)
    else:
        pytest.fail("Should have raised ValidationError for id null")

